import{_ as t,o as e,c as a,a2 as r}from"./chunks/framework.BWuWLRhz.js";const l="/assets/collection-root.CzqozG4O.jpg",_=JSON.parse('{"title":"📂 合集解析结果不完整","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting/collection-download-error.md","filePath":"troubleshooting/collection-download-error.md","lastUpdated":1793539672000}'),i={name:"troubleshooting/collection-download-error.md"};function n(s,o,c,d,p,h){return e(),a("div",null,[...o[0]||(o[0]=[r('<h1 id="📂-合集解析结果不完整" tabindex="-1">📂 合集解析结果不完整 <a class="header-anchor" href="#📂-合集解析结果不完整" aria-label="Permalink to &quot;📂 合集解析结果不完整&quot;">​</a></h1><h2 id="🔍-新版支持的解析范围" tabindex="-1">🔍 新版支持的解析范围 <a class="header-anchor" href="#🔍-新版支持的解析范围" aria-label="Permalink to &quot;🔍 新版支持的解析范围&quot;">​</a></h2><p>使用 <strong>uiya-yutto 0.3.4 及以上内核</strong>时，可以直接粘贴合集成员的 BV 播放地址。只要 B 站视频详情返回所属合集信息，点击「解析」就会展开整个合集，并列出成员视频中的各个分 P。</p><p>例如，<code>https://www.bilibili.com/video/BV17zDWYwEj8/?p=2</code> 属于「测试」合集。验证时合集有两个 BV，其中当前 BV 有两个分 P，解析结果共 <strong>3 个条目、2 个 BV</strong>。链接中的 <code>p=2</code> 不会把合集解析限制为当前分 P。合集内容可能随后续编辑发生变化。</p><p>没有所属合集信息的多 P 投稿，仍只展开当前 BV 的分 P。解析只获取列表元数据，点击「下载」后才会下载勾选的条目。</p><h2 id="💡-仍然只得到当前视频或其分-p-时" tabindex="-1">💡 仍然只得到当前视频或其分 P 时 <a class="header-anchor" href="#💡-仍然只得到当前视频或其分-p-时" aria-label="Permalink to &quot;💡 仍然只得到当前视频或其分 P 时&quot;">​</a></h2><ol><li><strong>确认正在使用新版内核。</strong> 旧版内核只会展开当前 BV 的分 P。源码 / uv 环境需拉取包含依赖升级的应用版本后执行 <code>uv sync</code>；便携版需使用内置新版内核的应用发行包。仅重启旧版应用不会更新其内置内核。</li><li><strong>更新环境后完全退出并重新打开应用。</strong> 已启动的 yutto server 会继续使用原先加载的内核；自定义 Python 环境也需要安装 <code>uiya-yutto==0.3.4</code> 或更新版本。</li><li><strong>确认视频是否属于合集。</strong> 普通多 P、视频列表和视频合集是不同的组织方式；视频标题里写着「合集」也不代表详情接口会返回所属合集信息。</li><li><strong>查看控制台的失败信息。</strong> 视频失效、访问权限和网络错误可能导致部分成员解析失败。</li></ol><h2 id="✅-使用合集入口排查" tabindex="-1">✅ 使用合集入口排查 <a class="header-anchor" href="#✅-使用合集入口排查" aria-label="Permalink to &quot;✅ 使用合集入口排查&quot;">​</a></h2><p>如果播放页仍无法完整展开，可以点击播放页的合集名称，在 UP 主空间打开合集，再复制合集入口地址解析。</p><p><img src="'+l+'" alt="collection-root"></p><p>合集入口通常形如 <code>https://space.bilibili.com/&lt;UP主ID&gt;/lists/&lt;合集ID&gt;?type=season</code>。这种地址明确指定合集，不依赖当前视频详情中的合集信息。</p><p>如果合集入口可以完整解析，而成员的播放页不行，请反馈两个地址、内核版本和控制台错误，便于定位接口差异。</p>',12)])])}const g=t(i,[["render",n]]);export{_ as __pageData,g as default};
